17	use crate::tensor::DeviceContext;
18	
19	const BF16_SIZE: usize = std::mem::size_of::<bf16>();
20	/// Per-buffer staging chunk. The measured 32 MiB geometry improves overlap and
21	/// limits the two pinned buffers to 64 MiB.
22	const STAGE_BYTES: usize = 32 << 20;
23	/// Widest fill team per rank, before the core-count cap.
24	const FILL_THREADS: usize = 8;
25	/// Small tails do not amortize dispatching work across the fill team.
26	const PARALLEL_FILL_MIN_BYTES: usize = 1 << 20;
27	
28	fn fill_threads() -> usize {
29	    static WIDTH: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
30	    *WIDTH.get_or_init(|| {
31	        let width = std::thread::available_parallelism()
32	            .expect("query available CPU parallelism")
33	            .get()
34	            .min(FILL_THREADS);
35	        if width < FILL_THREADS {
36	            log::info!("weight fill: {width} threads, capped by the core count");
37	        }
38	        width
39	    })
40	}
41	
42	fn as_uninit(src: &[u8]) -> &[MaybeUninit<u8>] {
43	    // SAFETY: MaybeUninit<u8> shares u8's layout and adds no validity
44	    // requirement, so widening an initialized slice is sound.
45	    unsafe { std::slice::from_raw_parts(src.as_ptr().cast(), src.len()) }
46	}
47	
48	struct FillPool {
49	    pool: ThreadPool,
50	    workers: usize,
51	}
52	
53	impl FillPool {
54	    fn new() -> Result<Self> {
55	        Self::with_workers(fill_threads())
56	    }
57	
58	    fn with_workers(workers: usize) -> Result<Self> {
59	        let pool = ThreadPoolBuilder::new()
60	            .num_threads(workers)
61	            .thread_name(|worker| format!("weight-fill-{worker}"))
62	            .build()
63	            .map_err(|e| anyhow::anyhow!("build weight-fill pool failed: {e}"))?;
64	        Ok(Self { pool, workers })
65	    }
66	
67	    fn copy(&self, src: &[u8], dst: &mut [MaybeUninit<u8>]) {
68	        debug_assert_eq!(src.len(), dst.len());
69	        if src.len() < PARALLEL_FILL_MIN_BYTES || self.workers == 1 {
70	            dst.copy_from_slice(as_uninit(src));
71	            return;
72	        }
73	        let per = src.len().div_ceil(self.workers);
74	        self.pool.scope(|scope| {
75	            for (src_part, dst_part) in src.chunks(per).zip(dst.chunks_mut(per)) {
76	                scope.spawn(move |_| dst_part.copy_from_slice(as_uninit(src_part)));
77	            }
78	        });
79	    }
80	
81	    fn gather_cols(
82	        &self,
83	        src: &[u8],
84	        stride_b: usize,
85	        off_b: usize,
86	        take_b: usize,
87	        rows: usize,
88	        dst: &mut [MaybeUninit<u8>],
89	    ) {
90	        debug_assert!(off_b + take_b <= stride_b);
91	        debug_assert!(rows * stride_b <= src.len());
92	        debug_assert_eq!(rows * take_b, dst.len());
93	        if dst.len() < PARALLEL_FILL_MIN_BYTES || self.workers == 1 {
94	            for (src_row, dst_row) in src[..rows * stride_b]
95	                .chunks(stride_b)
96	                .zip(dst.chunks_mut(take_b))
97	            {
98	                dst_row.copy_from_slice(as_uninit(&src_row[off_b..off_b + take_b]));
99	            }
100	            return;
101	        }
102	        let rows_per = rows.div_ceil(self.workers);
103	        self.pool.scope(|scope| {
104	            for (src_rows, dst_rows) in src[..rows * stride_b]
105	                .chunks(rows_per * stride_b)
106	                .zip(dst.chunks_mut(rows_per * take_b))
107	            {
108	                scope.spawn(move |_| {
109	                    for (src_row, dst_row) in
110	                        src_rows.chunks(stride_b).zip(dst_rows.chunks_mut(take_b))
111	                    {
112	                        dst_row.copy_from_slice(as_uninit(&src_row[off_b..off_b + take_b]));
113	                    }
114	                });
115	            }
116	        });
117	    }
118	}
119	
120	struct StagingBuf {
121	    pinned: PinnedHostSlice<bf16>,
122	    dma_done: CudaEvent,
123	}
124	
125	/// Validated execution plan for one strided column-shard upload.
126	pub(crate) struct ColShardPlan {
127	    stride_b: usize,
128	    off_b: usize,
129	    take_b: usize,
130	    rows: usize,
131	    dst_at: u64,
132	}
133	
134	/// Pinned double-buffering overlaps the source read with the H2D copy that
135	/// pageable `clone_htod` would serialize; sources are raw bytes.
136	pub(crate) struct WeightStager {
137	    stream: Arc<CudaStream>,
138	    bufs: [StagingBuf; 2],
139	    fill: FillPool,
140	    next: usize,
141	}
142	
143	impl WeightStager {
144	    pub(crate) fn new(ctx: &DeviceContext) -> Result<Self> {
145	        let make = || -> Result<StagingBuf> {
146	            // SAFETY: every byte a DMA reads is initialized by `stage_chunk`'s
147	            // fill callback first; buffer reuse is gated on `dma_done`.
148	            let pinned = unsafe { ctx.ctx.alloc_pinned::<bf16>(STAGE_BYTES / BF16_SIZE) }
149	                .map_err(|e| anyhow::anyhow!("pinned staging alloc failed: {e}"))?;
150	            let dma_done = ctx
151	                .ctx
152	                .new_event(Some(CUevent_flags::CU_EVENT_BLOCKING_SYNC))
153	                .map_err(|e| anyhow::anyhow!("staging event create failed: {e}"))?;
154	            Ok(StagingBuf { pinned, dma_done })
155	        };
156	        Ok(Self {
157	            stream: ctx.stream.clone(),
158	            bufs: [make()?, make()?],
159	            fill: FillPool::new()?,
160	            next: 0,
161	        })
162	    }
163	
164	    /// # Safety
165	    /// `dst_at` must address `src.len()` writable bytes still allocated on the
166	    /// stager's stream, as validated by [`prepare`].
167	    pub(crate) unsafe fn upload_at(&mut self, src: &[u8], dst_at: u64) -> Result<()> {
168	        for (i, chunk) in src.chunks(STAGE_BYTES).enumerate() {
169	            let chunk_at = dst_at + (i * STAGE_BYTES) as u64;
170	            let fill = |pool: &FillPool, stage: &mut [MaybeUninit<u8>]| pool.copy(chunk, stage);
171	            // SAFETY: the chunks partition `src`, so `chunk_at` stays inside
172	            // the validated destination range, with `chunk.len() <= STAGE_BYTES`.
173	            unsafe { self.stage_chunk(chunk.len(), chunk_at, fill) }?;
174	        }
175	        Ok(())
176	    }
177	
178	    /// # Safety
179	    /// `dst_at` must address the sum of `srcs` writable bytes still allocated
180	    /// on the stager's stream, as validated by [`prepare_bytes`].
181	    pub(crate) unsafe fn upload_slices_at(&mut self, srcs: &[&[u8]], dst_at: u64) -> Result<()> {
182	        let mut source = 0;
183	        let mut source_at = 0;
184	        let mut dst_offset = 0;
185	        let mut parts = Vec::new();
186	        while source < srcs.len() {
187	            let bytes =
188	                next_contiguous_chunk(srcs, &mut source, &mut source_at, STAGE_BYTES, &mut parts);
189	            let fill = |pool: &FillPool, stage: &mut [MaybeUninit<u8>]| {
190	                let mut at = 0;
191	                for part in &parts {
192	                    pool.copy(part, &mut stage[at..at + part.len()]);
193	                    at += part.len();
194	                }
195	            };
196	            // SAFETY: the chunks partition the validated concatenated source.
197	            unsafe { self.stage_chunk(bytes, dst_at + dst_offset as u64, fill) }?;
198	            dst_offset += bytes;
199	        }
200	        Ok(())
201	    }
202	
203	    /// # Safety
204	    /// `plan` must come from [`prepare_cols`] for this `src`, with its
205	    /// destination still allocated on the stager's stream.
206	    pub(crate) unsafe fn upload_cols_at(&mut self, src: &[u8], plan: &ColShardPlan) -> Result<()> {
207	        let rows_per_chunk = STAGE_BYTES / plan.take_b;
208	        let mut row = 0;
209	        while row < plan.rows {
210	            let chunk_rows = rows_per_chunk.min(plan.rows - row);
211	            let dst_at = plan.dst_at + (row * plan.take_b) as u64;
212	            let fill = |pool: &FillPool, stage: &mut [MaybeUninit<u8>]| {
213	                pool.gather_cols(
214	                    &src[row * plan.stride_b..],
215	                    plan.stride_b,
216	                    plan.off_b,
217	                    plan.take_b,
218	                    chunk_rows,
219	                    stage,
220	                );
221	            };
222	            // SAFETY: the destination rows lie inside the validated range per
223	            // the rows x take bound, with `chunk_rows * take_b <= STAGE_BYTES`.
224	            unsafe { self.stage_chunk(chunk_rows * plan.take_b, dst_at, fill) }?;
225	            row += chunk_rows;
226	        }
227	        Ok(())
228	    }
229	
230	    /// # Safety
231	    /// `dst_at` must address `bytes <= STAGE_BYTES` writable bytes on the
232	    /// stager's stream, and `fill` must initialize the `bytes` it is given.
233	    unsafe fn stage_chunk(
234	        &mut self,
235	        bytes: usize,
236	        dst_at: u64,
237	        fill: impl FnOnce(&FillPool, &mut [MaybeUninit<u8>]),
238	    ) -> Result<()> {
239	        let idx = self.next;
240	        self.next = (self.next + 1) % self.bufs.len();
241	        let buf = &mut self.bufs[idx];
242	        buf.dma_done
243	            .synchronize()
244	            .map_err(|e| anyhow::anyhow!("staging drain failed: {e}"))?;
245	        let stage = buf
246	            .pinned
247	            .as_mut_ptr()
248	            .map_err(|e| anyhow::anyhow!("staging pointer failed: {e}"))?
249	            .cast::<u8>();
250	        // SAFETY: the pinned allocation contains STAGE_BYTES bytes and this
251	        // function requires bytes <= STAGE_BYTES.
252	        let staged =
253	            unsafe { std::slice::from_raw_parts_mut(stage.cast::<MaybeUninit<u8>>(), bytes) };
254	        fill(&self.fill, staged);
255	        // SAFETY: `fill` initialized `bytes` at `stage` and `dst_at` is valid
256	        // per the contract; the buffer outlives the copy (`dma_done` or the
257	        // drain-or-abort branches), and the event synchronize above bound the
258	        // context to this thread.
259	        let copied = unsafe {
260	            let staged = std::slice::from_raw_parts(stage.cast_const(), bytes);
261	            memcpy_htod_async(dst_at, staged, self.stream.cu_stream())
262	        };
263	        if let Err(copy_err) = copied {
264	            // An async-API error can stem from earlier work on the stream and
265	            // does not prove this copy never started.
266	            drain_or_abort(
267	                &self.stream,
268	                &format!("staged H2D copy failed ({copy_err})"),
269	            );
270	            return Err(anyhow::anyhow!("staged H2D copy failed: {copy_err}"));
271	        }
272	        if let Err(record_err) = buf.dma_done.record(&self.stream) {
273	            // The copy is in flight with no event covering it.
274	            drain_or_abort(
275	                &self.stream,
276	                &format!("staging record failed ({record_err})"),
277	            );
278	            return Err(anyhow::anyhow!("staging record failed: {record_err}"));
279	        }
280	        Ok(())
281	    }
282	}
283	
284	/// Fills `parts` (cleared first, reused across calls) with the source slices
285	/// of the next chunk of at most `limit` bytes; returns the chunk's size.
286	/// `limit` is a parameter so the boundary coverage below runs on dozens of
287	/// bytes instead of a STAGE_BYTES-sized fixture.
288	fn next_contiguous_chunk<'a>(
289	    srcs: &'a [&'a [u8]],
290	    source: &mut usize,
291	    source_at: &mut usize,
292	    limit: usize,
293	    parts: &mut Vec<&'a [u8]>,
294	) -> usize {
295	    parts.clear();
296	    let mut bytes = 0;
297	    while *source < srcs.len() && bytes < limit {
298	        let src = srcs[*source];
299	        if src.is_empty() {
300	            *source += 1;
301	            *source_at = 0;
302	            continue;
303	        }
304	        let take = (limit - bytes).min(src.len() - *source_at);
305	        parts.push(&src[*source_at..*source_at + take]);
306	        bytes += take;
307	        *source_at += take;
308	        if *source_at == src.len() {
309	            *source += 1;
310	            *source_at = 0;
311	        }
312	    }
313	    bytes
314	}
315	
316	// Both the stager's events and `dst`'s stream-ordered allocation are only
317	// ordered against work on `stream`, which must be the stager's own stream.
318	fn ensure_uploadable<T>(stream: &Arc<CudaStream>, dst: &CudaSlice<T>) -> Result<()> {
319	    anyhow::ensure!(
320	        Arc::ptr_eq(dst.stream(), stream),
321	        "staged upload into a buffer allocated on a different stream than the stager's"
322	    );
323	    anyhow::ensure!(
324	        !crate::tensor::has_stream_override(),
325	        "staged upload under a thread-local stream override is unsupported"
326	    );
327	    Ok(())
328	}
329	
330	pub(crate) fn prepare_bytes(
331	    stream: &Arc<CudaStream>,
332	    srcs: &[&[u8]],
333	    dst: &mut CudaSlice<u8>,
334	) -> Result<u64> {
335	    ensure_uploadable(stream, dst)?;
336	    let bytes = srcs.iter().try_fold(0usize, |total, src| {
337	        total
338	            .checked_add(src.len())
339	            .ok_or_else(|| anyhow::anyhow!("staged byte upload source length overflow"))
340	    })?;
341	    anyhow::ensure!(
342	        bytes == dst.len(),
343	        "staged byte upload size mismatch: {bytes} source bytes vs dst len {}",
344	        dst.len()
345	    );
346	    let (dst_ptr, _dst_order) = dst.device_ptr_mut(stream);
347	    Ok(dst_ptr)
348	}
349	
350	/// Validates a contiguous staged upload and returns the destination device
351	/// address for a deferred [`WeightStager::upload_at`].
352	pub(crate) fn prepare(
353	    stream: &Arc<CudaStream>,
354	    src: &[u8],
355	    dst: &mut CudaSlice<bf16>,
356	    dst_offset: usize,
357	) -> Result<u64> {
358	    ensure_uploadable(stream, dst)?;
359	    anyhow::ensure!(
360	        src.len().is_multiple_of(BF16_SIZE),
361	        "staged upload source of {} bytes is not a whole number of bf16 elements",
362	        src.len()
363	    );
364	    anyhow::ensure!(
365	        dst_offset
366	            .checked_mul(BF16_SIZE)
367	            .and_then(|off| off.checked_add(src.len()))
368	            .is_some_and(|end| end <= dst.len() * BF16_SIZE),
369	        "staged upload out of bounds: dst_offset {dst_offset} + src bytes {} > dst len {}",
370	        src.len(),
371	        dst.len()
372	    );
373	    // Dropping the guard immediately is fine only because the runtime context
374	    // disables cudarc event tracking; revisit if that ever changes.
375	    let (dst_ptr, _dst_order) = dst.device_ptr_mut(stream);
376	    Ok(dst_ptr + (dst_offset * BF16_SIZE) as u64)
377	}
378	
379	/// Validates a strided staged upload and returns its execution plan for a
380	/// deferred [`WeightStager::upload_cols_at`] (column counts in elements).
381	pub(crate) fn prepare_cols(
382	    stream: &Arc<CudaStream>,
383	    src: &[u8],
384	    total_cols: usize,
385	    col_offset: usize,
386	    take: usize,
387	    dst: &mut CudaSlice<bf16>,
388	) -> Result<ColShardPlan> {
389	    ensure_uploadable(stream, dst)?;
390	    let stride_b = total_cols
391	        .checked_mul(BF16_SIZE)
392	        .filter(|&s| s > 0 && src.len().is_multiple_of(s));
393	    anyhow::ensure!(
394	        stride_b.is_some(),
395	        "strided upload source of {} bytes is not a multiple of {total_cols} bf16 columns",
396	        src.len()
397	    );
398	    let stride_b = stride_b.unwrap();
399	    anyhow::ensure!(
400	        col_offset
401	            .checked_add(take)
402	            .is_some_and(|end| end <= total_cols),
403	        "col range out of bounds: col_offset={col_offset} take={take} total_cols={total_cols}"
404	    );
405	    let take_b = take * BF16_SIZE;
406	    anyhow::ensure!(
407	        (1..=STAGE_BYTES).contains(&take_b),
408	        "column shard width {take} outside 1..={}",
409	        STAGE_BYTES / BF16_SIZE
410	    );
411	    let rows = src.len() / stride_b;
412	    anyhow::ensure!(
413	        rows.checked_mul(take).is_some_and(|n| n == dst.len()),
414	        "staged upload shape mismatch: {rows} rows x {take} cols vs dst len {}",
415	        dst.len()
416	    );
417	    let (dst_ptr, _dst_order) = dst.device_ptr_mut(stream);
418	    Ok(ColShardPlan {
419	        stride_b,
420	        off_b: col_offset * BF16_SIZE,
421	        take_b,
422	        rows,
423	        dst_at: dst_ptr,
424	    })
425	}
426	
427	impl Drop for WeightStager {
428	    fn drop(&mut self) {
429	        // PinnedHostSlice's drop only waits on its embedded, never-recorded
430	        // event; drain ours instead and fail closed when the DMA state is
431	        // unknown.
432	        for buf in &self.bufs {
433	            if let Err(err) = buf.dma_done.synchronize() {
434	                error!(
435	                    "staging DMA drain failed on drop ({err}); aborting instead of freeing pinned memory under an in-flight DMA"
436	                );
437	                std::process::abort();
438	            }
439	        }
440	    }
441	}
442	
443	pub(super) fn drain_or_abort(stream: &CudaStream, context: &str) {
444	    if let Err(sync_err) = stream.synchronize() {
445	        error!(
446	            "{context}; stream drain failed ({sync_err}); aborting instead of freeing pinned memory under an in-flight DMA"
447	        );
448	        std::process::abort();
449	    }
450	}
451	
452	#[cfg(test)]
453	mod tests {
454	    use super::*;
455	
456	    #[test]
457	    fn fill_pool_strided_matches_scalar_gather() {
458	        // Fixed width: `FillPool::new()` would collapse to the serial path on a
459	        // single-CPU runner, so the parallel case below would not be exercised.
460	        let pool = FillPool::with_workers(2).expect("build fill pool");
461	        for &(rows, total_cols, col_offset, take) in &[
462	            (1usize, 7usize, 0usize, 7usize),
463	            (3, 8, 2, 5),
464	            (4, 5, 1, 4),
465	            (9, 6, 3, 3),
466	            // Past the parallel threshold, with rows that do not divide evenly.
467	            (601, 2560, 640, 1280),
468	        ] {
469	            let (stride_b, off_b, take_b) = (
470	                total_cols * BF16_SIZE,
471	                col_offset * BF16_SIZE,
472	                take * BF16_SIZE,
473	            );
474	            let mut buf = vec![0u8; rows * stride_b];
475	            for (i, b) in buf.iter_mut().enumerate() {
476	                *b = (i % 251) as u8;
477	            }
478	            let src = &buf[..];
479	            let mut dst = vec![MaybeUninit::uninit(); rows * take_b];
480	            pool.gather_cols(src, stride_b, off_b, take_b, rows, &mut dst);
481	            // SAFETY: gather_cols wrote every byte of `dst`.
482	            let dst = unsafe { std::slice::from_raw_parts(dst.as_ptr().cast::<u8>(), dst.len()) };
483	            let mut expect = Vec::with_capacity(rows * take_b);
484	            for r in 0..rows {
485	                for c in 0..take_b {
486	                    expect.push(src[r * stride_b + off_b + c]);
487	                }
488	            }
489	            assert_eq!(
490	                dst, expect,
491	                "rows={rows} total_cols={total_cols} col_offset={col_offset} take={take}"
492	            );
493	        }
494	    }
495	
496	    #[test]
497	    fn contiguous_chunks_preserve_source_bytes() {
498	        let limit = 46;
499	        let first = vec![1u8; limit - 2];
500	        let second = [2u8, 3, 4, 5];
501	        let sources: [&[u8]; 3] = [&first, &[], &second];
502	        let mut source = 0;
503	        let mut source_at = 0;
504	        let mut actual = Vec::new();
505	        let mut sizes = Vec::new();
506	        let mut parts = Vec::new();
507	        while source < sources.len() {
508	            let bytes =
509	                next_contiguous_chunk(&sources, &mut source, &mut source_at, limit, &mut parts);
510	            sizes.push(bytes);
511	            actual.extend(parts.iter().copied().flatten().copied());
512	        }
513	        let expected: Vec<u8> = sources.into_iter().flatten().copied().collect();
514	        assert_eq!(sizes, [limit, 2]);
515	        assert_eq!(actual, expected);
516	    }
517	}
