141	impl WeightPrefetch {
142	    pub fn spawn(shard_paths: &[String]) -> Self {
143	        const CHUNK: u64 = 16 << 20;
144	        const THREADS: usize = 8;
145	        /// Below this the prefetch cannot outrun the load path it shares the
146	        /// device with, and only contends with it.
147	        const FLOOR_BYTES_PER_SEC: f64 = 1e9;
148	        /// Read enough that the rate is the device's and not thread start-up.
149	        const PROBE_BYTES: u64 = 512 << 20;
150	
151	        let stats = Arc::new(PrefetchStats::default());
152	        let mut files: Vec<(Arc<fs::File>, u64, String)> = Vec::new();
153	        let mut chunks: Vec<(usize, u64)> = Vec::new();
154	        let mut unreadable_shards = 0usize;
155	        for path in shard_paths {
156	            let meta = fs::File::open(path).and_then(|file| {
157	                let len = file.metadata()?.len();
158	                Ok((file, len))
159	            });
160	            match meta {
161	                Ok((file, len)) => {
162	                    let idx = files.len();
163	                    files.push((Arc::new(file), len, path.clone()));
164	                    chunks.extend((0..len).step_by(CHUNK as usize).map(|off| (idx, off)));
165	                }
166	                Err(err) => {
167	                    unreadable_shards += 1;
168	                    stats.record_first_error(|| format!("{path}: {err}"));
169	                }
170	            }
171	        }
172	
173	        let cancel = Arc::new(AtomicBool::new(false));
174	        let mut workers = Vec::new();
175	        let mut spawn_failures = 0usize;
176	        let threads = THREADS.min(chunks.len());
177	        if !chunks.is_empty() {
178	            let total_bytes: u64 = files.iter().map(|(_, len, _)| len).sum();
179	            let num_files = files.len();
180	            let files = Arc::new(files);
181	            let chunks = Arc::new(chunks);
182	            let next = Arc::new(AtomicUsize::new(0));
183	            let read_bytes = Arc::new(AtomicU64::new(0));
184	            let started = Instant::now();
185	            for _ in 0..threads {
186	                let worker = {
187	                    let (files, chunks, next) = (files.clone(), chunks.clone(), next.clone());
188	                    let (cancel, stats) = (cancel.clone(), stats.clone());
189	                    let read_bytes = read_bytes.clone();
190	                    std::thread::Builder::new()
191	                        .name("weight-prefetch".into())
192	                        .spawn(move || {
193	                            // A resident checkpoint reads no chunk at all.
194	                            let mut buf = Vec::new();
195	                            while !cancel.load(Ordering::Relaxed) {
196	                                let i = next.fetch_add(1, Ordering::Relaxed);
197	                                let Some(&(file_idx, off)) = chunks.get(i) else {
198	                                    break;
199	                                };
200	                                let (file, len, path) = &files[file_idx];
201	                                if chunk_looks_resident(file, off) {
202	                                    continue;
203	                                }
204	                                let want = CHUNK.min(len - off) as usize;
205	                                if buf.is_empty() {
206	                                    buf = vec![0u8; CHUNK as usize];
207	                                }
208	                                match file.read_exact_at(&mut buf[..want], off) {
209	                                    Ok(()) => {
210	                                        let read = want as u64;
211	                                        let done =
212	                                            read_bytes.fetch_add(read, Ordering::Relaxed) + read;
213	                                        if done >= PROBE_BYTES && done - read < PROBE_BYTES {
214	                                            let rate =
215	                                                done as f64 / started.elapsed().as_secs_f64();
216	                                            if rate < FLOOR_BYTES_PER_SEC {
217	                                                cancel.store(true, Ordering::Relaxed);
218	                                                info!(
219	                                                    "Weight prefetch standing down: source reads at {:.2} GB/s, leaving the device to the load path",
220	                                                    rate / 1e9
221	                                                );
222	                                            }
223	                                        }
224	                                    }
225	                                    Err(err) => {
226	                                        stats.read_errors.fetch_add(1, Ordering::Relaxed);
227	                                        stats
228	                                            .record_first_error(|| format!("{path}@{off}: {err}"));
229	                                    }
230	                                }
231	                            }
232	                        })
233	                };
234	                match worker {
235	                    Ok(handle) => workers.push(handle),
236	                    Err(err) => {
237	                        spawn_failures += 1;
238	                        stats.record_first_error(|| format!("worker spawn: {err}"));
239	                    }
240	                }
241	            }
242	            if !workers.is_empty() {
243	                info!(
244	                    "Prefetching {num_files} weight shard(s) ({:.1} GB) on {} threads",
245	                    total_bytes as f64 / 1e9,
246	                    workers.len()
247	                );
248	            }
249	        }
250	        Self {
251	            cancel,
252	            stats,
253	            unreadable_shards,
254	            spawn_failures,
255	            workers,
256	        }
257	    }
258	}
