260	impl Drop for WeightPrefetch {
261	    fn drop(&mut self) {
262	        self.cancel.store(true, Ordering::Relaxed);
263	        let mut panicked = 0usize;
264	        for worker in self.workers.drain(..) {
265	            if let Err(payload) = worker.join() {
266	                panicked += 1;
267	                let message = payload
268	                    .downcast_ref::<&str>()
269	                    .map(|s| (*s).to_string())
270	                    .or_else(|| payload.downcast_ref::<String>().cloned())
271	                    .unwrap_or_else(|| "non-string panic payload".to_string());
272	                self.stats
273	                    .record_first_error(|| format!("worker panic: {message}"));
274	            }
275	        }
276	        let read_errors = self.stats.read_errors.load(Ordering::Relaxed);
277	        if self.unreadable_shards + self.spawn_failures + read_errors + panicked > 0 {
278	            let first = match self.stats.first_error.lock() {
279	                Ok(guard) => guard.clone(),
280	                Err(poisoned) => poisoned.into_inner().clone(),
281	            };
282	            warn!(
283	                "weight prefetch incomplete: {} unreadable shard(s), {} worker spawn failure(s), {} chunk read error(s), {} panic(s); first error: {}",
284	                self.unreadable_shards,
285	                self.spawn_failures,
286	                read_errors,
287	                panicked,
288	                first.as_deref().unwrap_or("unknown")
289	            );
290	        }
291	    }
292	}
