369	/// Aligned payloads borrow zero-copy; misaligned ones (legal in safetensors)
370	/// decode into an owned buffer, since a misaligned bf16 view is UB.
371	#[allow(clippy::cast_ptr_alignment)]
372	fn tensor_bf16_cow<'d>(
373	    tensor: &safetensors::tensor::TensorView<'d>,
374	    name: &str,
375	) -> Result<Cow<'d, [bf16]>> {
376	    let data = tensor_bf16_bytes(tensor, name)?;
377	    if (data.as_ptr() as usize).is_multiple_of(std::mem::align_of::<bf16>()) {
378	        // SAFETY: alignment checked; any bit pattern is a valid bf16.
379	        Ok(Cow::Borrowed(unsafe {
380	            std::slice::from_raw_parts(
381	                data.as_ptr().cast::<bf16>(),
382	                data.len() / std::mem::size_of::<bf16>(),
383	            )
384	        }))
385	    } else {
386	        Ok(Cow::Owned(
387	            data.as_chunks::<2>()
388	                .0
389	                .iter()
390	                .map(|&b| bf16::from_bits(u16::from_le_bytes(b)))
391	                .collect(),
392	        ))
393	    }
394	}
