637	    pub fn matrix(&mut self, name: &str, rows: usize, cols: usize) -> Result<SlotId> {
638	        self.ensure_recording()?;
639	        let src = self.tensor_2d(name, rows, cols)?;
640	        let mut data = self.alloc_timed(rows * cols, name)?;
641	        let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, 0)?;
642	        self.pending.push(PendingUpload::Contiguous { src, dst_at });
643	        Ok(self.push_slot(data, rows, cols))
644	    }
