985	///
986	/// For small integer lookup tables that live on the host (e.g. EAGLE-3's `d2t`
987	/// draft→target vocab offset map), not weights destined for a GEMM.
988	pub fn load_tensor_i64_host(
989	    shards: &[SafeTensors],
990	    weight_map: &HashMap<String, usize>,
991	    name: &str,
992	) -> Result<Vec<i64>> {
993	    let tensor = find_tensor(shards, weight_map, name)?;
994	
995	    if tensor.dtype() != Dtype::I64 {
996	        return Err(anyhow::anyhow!(
997	            "I64 tensor '{}': expected dtype I64, got {:?}",
998	            name,
999	            tensor.dtype()
1000	        ));
1001	    }
1002	    if tensor.shape().len() != 1 {
1003	        return Err(anyhow::anyhow!(
1004	            "I64 tensor '{}': expected 1D, got shape {:?}",
1005	            name,
1006	            tensor.shape()
1007	        ));
1008	    }
1009	    let data = tensor.data();
1010	    if data.len() % 8 != 0 {
1011	        return Err(anyhow::anyhow!(
1012	            "I64 tensor '{}': data length {} not multiple of 8",
1013	            name,
1014	            data.len()
1015	        ));
1016	    }
1017	    Ok(data
1018	        .as_chunks::<8>()
1019	        .0
1020	        .iter()
1021	        .map(|&b| i64::from_le_bytes(b))
1022	        .collect())
1023	}
