1099	    #[test]
1100	    fn tensor_f32_cow_borrows_aligned_and_decodes_unaligned() {
1101	        let vals: [u32; 4] = [0x3f80_0000, 0x0000_0001, 0xbf12_3456, 0x7f80_0001];
1102	        let mut bytes = vec![0u8; vals.len() * 4 + 3];
1103	        // A Vec<u8> base has no alignment guarantee; derive both offsets from
1104	        // the actual address so each branch is forced deterministically.
1105	        let base = bytes.as_ptr() as usize;
1106	        let aligned_off = base.next_multiple_of(4) - base;
1107	        for (off, expect_borrowed) in [(aligned_off, true), (aligned_off + 1, false)] {
1108	            for (i, v) in vals.iter().enumerate() {
1109	                bytes[off + i * 4..off + i * 4 + 4].copy_from_slice(&v.to_le_bytes());
1110	            }
1111	            let view = TensorView::new(
1112	                Dtype::F32,
1113	                vec![vals.len()],
1114	                &bytes[off..off + vals.len() * 4],
1115	            )
1116	            .unwrap();
1117	            let cow = tensor_f32_cow(&view, "w").unwrap();
1118	            assert_eq!(
1119	                matches!(cow, Cow::Borrowed(_)),
1120	                expect_borrowed,
1121	                "off={off}"
1122	            );
1123	            let got: Vec<u32> = cow.iter().map(|f| f.to_bits()).collect();
1124	            assert_eq!(got, vals, "off={off}");
1125	        }
1126	    }
