1131	        let bf16_view = TensorView::new(Dtype::BF16, vec![4], &bytes).unwrap();
1132	        assert!(tensor_f32_cow(&bf16_view, "w").is_ok());
1133	        let f16_view = TensorView::new(Dtype::F16, vec![4], &bytes).unwrap();
1134	        assert!(tensor_f32_cow(&f16_view, "w").is_err());
1135	        let f32_2d_view = TensorView::new(Dtype::F32, vec![2, 1], &bytes).unwrap();
1136	        assert!(tensor_f32_cow(&f32_2d_view, "w").is_err());
1137	        let bf16_2d_view = TensorView::new(Dtype::BF16, vec![2, 2], &bytes).unwrap();
1138	        assert!(tensor_f32_cow(&bf16_2d_view, "w").is_err());
1139	    }
