1141	    #[test]
1142	    fn tensor_bf16_cow_borrows_aligned_and_decodes_unaligned() {
1143	        let vals: [u16; 4] = [0x3f80, 0x0001, 0xbf12, 0x7fff];
1144	        let mut bytes = vec![0u8; vals.len() * 2 + 3];
1145	        // A Vec<u8> base has no alignment guarantee; derive both offsets from
1146	        // the actual address so each branch is forced deterministically.
