125	/// Validated execution plan for one strided column-shard upload.
126	pub(crate) struct ColShardPlan {
127	    stride_b: usize,
128	    off_b: usize,
129	    take_b: usize,
130	    rows: usize,
131	    dst_at: u64,
132	}
