427	impl Drop for WeightStager {
428	    fn drop(&mut self) {
429	        // PinnedHostSlice's drop only waits on its embedded, never-recorded
430	        // event; drain ours instead and fail closed when the DMA state is
431	        // unknown.
432	        for buf in &self.bufs {
433	            if let Err(err) = buf.dma_done.synchronize() {
434	                error!(
435	                    "staging DMA drain failed on drop ({err}); aborting instead of freeing pinned memory under an in-flight DMA"
436	                );
437	                std::process::abort();
438	            }
439	        }
440	    }
441	}
442	
443	pub(super) fn drain_or_abort(stream: &CudaStream, context: &str) {
444	    if let Err(sync_err) = stream.synchronize() {
445	        error!(
446	            "{context}; stream drain failed ({sync_err}); aborting instead of freeing pinned memory under an in-flight DMA"
447	        );
448	        std::process::abort();
449	    }
450	}
