481	            // SAFETY: gather_cols wrote every byte of `dst`.
482	            let dst = unsafe { std::slice::from_raw_parts(dst.as_ptr().cast::<u8>(), dst.len()) };
483	            let mut expect = Vec::with_capacity(rows * take_b);
