321	/// Deserialize memory-mapped shard data into `SafeTensors` views.
322	pub fn deserialize_shards(mmaps: &[Mmap]) -> Result<Vec<SafeTensors<'_>>> {
323	    mmaps
324	        .iter()
325	        .map(|m| {
326	            SafeTensors::deserialize(m).map_err(|e| anyhow::anyhow!("Deserialize error: {}", e))
327	        })
328	        .collect()
