484	/// Validating BF16 checkpoint loader backed by pinned staging: every method
485	/// checks dtype and config-derived dimensions at the load boundary; payload
486	/// alignment is not required. Uploads run in [`Self::finish`], after every
487	/// tensor has been validated.
488	pub struct StagedWeightLoader<'a> {
489	    ctx: &'a DeviceContext,
490	    stager: WeightStager,
491	    shards: &'a [SafeTensors<'a>],
492	    weight_map: &'a HashMap<String, usize>,
493	    slots: Vec<Slot>,
494	    vec_slots: Vec<VecSlot>,
495	    pending: Vec<PendingUpload<'a>>,
496	    retained: Vec<Vec<bf16>>,
497	    finished: bool,
498	    failed: bool,
499	    alloc_ms: f64,
500	}
501	
502	impl<'a> StagedWeightLoader<'a> {
503	    pub fn new(
504	        ctx: &'a DeviceContext,
505	        shards: &'a [SafeTensors<'a>],
506	        weight_map: &'a HashMap<String, usize>,
507	    ) -> Result<Self> {
508	        Ok(Self {
509	            ctx,
510	            stager: WeightStager::new(ctx)?,
511	            shards,
512	            weight_map,
513	            slots: Vec::new(),
514	            vec_slots: Vec::new(),
515	            pending: Vec::new(),
516	            retained: Vec::new(),
517	            finished: false,
518	            failed: false,
519	            alloc_ms: 0.0,
520	        })
521	    }
522	
523	    fn ensure_recording(&self) -> Result<()> {
524	        anyhow::ensure!(
525	            !self.finished && !self.failed,
526	            "staged loader already finished"
527	        );
528	        Ok(())
529	    }
530	
531	    fn push_slot(&mut self, data: CudaSlice<bf16>, rows: usize, cols: usize) -> SlotId {
532	        self.slots.push(Slot {
533	            data: Some(data),
534	            rows,
535	            cols,
536	        });
537	        SlotId(self.slots.len() - 1)
538	    }
539	
540	    /// Executes every recorded upload; must run before [`Self::take`].
541	    pub fn finish(&mut self) -> Result<()> {
542	        anyhow::ensure!(
543	            !self.finished && !self.failed,
544	            "staged loader already finished"
545	        );
546	        // Poisoned until every upload lands; a failed finish cannot retry
547	        // vacuously over the drained op list.
548	        self.failed = true;
549	        let uploads = self.pending.len();
550	        let t_upload = std::time::Instant::now();
551	        if let Err(err) = self.execute_uploads() {
552	            // Soundness closes here, not in Drop (skippable via `mem::forget`):
553	            // no submitted copy may outlive this call unresolved.
554	            staging::drain_or_abort(&self.ctx.stream, "staged upload failure");
555	            self.retained.clear();
556	            return Err(err);
557	        }
558	        self.retained.clear();
559	        self.failed = false;
560	        self.finished = true;
561	        info!(
562	            "weight load: {} uploads, alloc_api_wall {:.0}ms, execute_and_drain_wall {:.0}ms",
563	            uploads,
564	            self.alloc_ms,
565	            t_upload.elapsed().as_secs_f64() * 1e3
566	        );
567	        Ok(())
568	    }
569	
570	    fn execute_uploads(&mut self) -> Result<()> {
571	        for op in std::mem::take(&mut self.pending) {
572	            match op {
573	                // SAFETY: the destination is owned by `self.slots` (`take`
574	                // refuses to hand it out before a successful finish) and the
575	                // range was validated by prepare/prepare_cols at record time.
576	                PendingUpload::Contiguous { src, dst_at } => unsafe {
577	                    self.stager.upload_at(src, dst_at)?;
578	                },
579	                PendingUpload::ColShard { src, plan } => unsafe {
580	                    self.stager.upload_cols_at(src, &plan)?;
581	                },
582	                // SAFETY: destination validated at record time; sources
583	                // outlive the drain (borrowed: shards; owned: retained first).
584	                PendingUpload::Vector { src, dst_at } => {
585	                    let bytes = match src {
586	                        Cow::Borrowed(borrowed) => bf16_bytes(borrowed),
587	                        Cow::Owned(owned) => {
588	                            self.retained.push(owned);
589	                            bf16_bytes(self.retained.last().expect("just pushed"))
590	                        }
591	                    };
592	                    unsafe {
593	                        memcpy_htod_async(dst_at, bytes, self.ctx.stream.cu_stream())
594	                            .map_err(|e| anyhow::anyhow!("vector upload failed: {e}"))?;
595	                    }
596	                }
597	            }
598	        }
599	        self.ctx.sync()
600	    }
601	
602	    /// Redeems a recorded matrix after a successful [`Self::finish`].
603	    pub fn take(&mut self, slot: SlotId) -> DeviceMatrix {
604	        assert!(self.finished, "take before successful finish");
605	        let slot = &mut self.slots[slot.0];
606	        DeviceMatrix {
607	            data: slot.data.take().expect("slot already taken"),
608	            rows: slot.rows,
609	            cols: slot.cols,
610	        }
611	    }
