613	    fn tensor_2d(&self, name: &str, rows: usize, cols: usize) -> Result<&'a [u8]> {
614	        let tensor = find_tensor(self.shards, self.weight_map, name)?;
615	        let shape = tensor.shape();
616	        anyhow::ensure!(
617	            shape.len() == 2,
618	            "Tensor '{name}' expected 2D, got shape {shape:?}"
619	        );
620	        anyhow::ensure!(
621	            shape[0] == rows && shape[1] == cols,
622	            "Tensor '{name}' has shape {shape:?}, config expects [{rows}, {cols}]"
623	        );
624	        tensor_bf16_bytes(&tensor, name)
625	    }
626	
627	    fn alloc_timed(&mut self, elems: usize, name: &str) -> Result<CudaSlice<bf16>> {
628	        let t = std::time::Instant::now();
629	        // SAFETY: overwritten by its recorded upload before `take` can
630	        // expose it.
631	        let data = unsafe { self.ctx.stream.alloc::<bf16>(elems) }
632	            .map_err(|e| anyhow::anyhow!("Alloc failed for '{name}': {e}"))?;
633	        self.alloc_ms += t.elapsed().as_secs_f64() * 1e3;
634	        Ok(data)
635	    }
636	
637	    pub fn matrix(&mut self, name: &str, rows: usize, cols: usize) -> Result<SlotId> {
638	        self.ensure_recording()?;
639	        let src = self.tensor_2d(name, rows, cols)?;
640	        let mut data = self.alloc_timed(rows * cols, name)?;
641	        let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, 0)?;
642	        self.pending.push(PendingUpload::Contiguous { src, dst_at });
643	        Ok(self.push_slot(data, rows, cols))
644	    }
