852	/// Load one column range of a column-parallel 2D tensor. `global` is the
853	/// config-derived `(rows, cols)` of the full unsharded tensor; the header must
854	/// match it before the slice is taken.
855	pub fn load_tensor_2d_col_shard(
856	    ctx: &DeviceContext,
857	    shards: &[SafeTensors],
858	    weight_map: &HashMap<String, usize>,
859	    name: &str,
860	    col_offset: usize,
861	    cols: usize,
862	    global: (usize, usize),
863	) -> Result<DeviceMatrix> {
864	    let tensor = find_tensor(shards, weight_map, name)?;
865	    let (rows, total_cols) = tensor_2d_dims(&tensor, name)?;
866	    ensure_global_shape(name, (rows, total_cols), global)?;
867	    if col_offset + cols > total_cols {
868	        return Err(anyhow::anyhow!(
869	            "2D col shard out of bounds for '{}': col_offset={} cols={} total_cols={}",
870	            name,
871	            col_offset,
872	            cols,
873	            total_cols
874	        ));
875	    }
876	    let elems = tensor_bf16_cow(&tensor, name)?;
877	    let host = gather_cols(&elems, rows, total_cols, col_offset, cols);
878	    DeviceMatrix::from_host(ctx, &host, rows, cols)
879	}
