881	/// Load a 2D tensor assembled from multiple row ranges of one source tensor,
882	/// stitched in `ranges` order: each entry is (row_offset, rows). `global` is
883	/// the config-derived `(rows, cols)` of the full source tensor; the header
884	/// must match it before any slice is taken.
885	pub fn load_tensor_2d_row_stitch(
886	    ctx: &DeviceContext,
887	    shards: &[SafeTensors],
888	    weight_map: &HashMap<String, usize>,
889	    name: &str,
890	    ranges: &[(usize, usize)],
891	    global: (usize, usize),
892	) -> Result<DeviceMatrix> {
893	    let tensor = find_tensor(shards, weight_map, name)?;
894	    let (total_rows, cols) = tensor_2d_dims(&tensor, name)?;
895	    ensure_global_shape(name, (total_rows, cols), global)?;
896	    let mut total = 0usize;
897	    for &(row_offset, rows) in ranges {
898	        check_row_range(name, row_offset, rows, total_rows)?;
899	        total += rows;
900	    }
901	    let elems = tensor_bf16_cow(&tensor, name)?;
902	    let mut host = Vec::with_capacity(total * cols);
903	    for &(row_offset, rows) in ranges {
904	        let start = row_offset * cols;
905	        host.extend_from_slice(&elems[start..start + rows * cols]);
906	    }
907	    DeviceMatrix::from_host(ctx, &host, total, cols)
908	}
