910	/// Load a 1D BF16 tensor assembled from multiple element ranges of one source
911	/// tensor, stitched in `ranges` order: each entry is (offset, len).
912	pub fn load_tensor_1d_stitch(
913	    ctx: &DeviceContext,
914	    shards: &[SafeTensors],
915	    weight_map: &HashMap<String, usize>,
916	    name: &str,
917	    ranges: &[(usize, usize)],
918	) -> Result<DeviceVec> {
919	    let tensor = find_tensor(shards, weight_map, name)?;
920	    let elems = tensor_bf16_cow(&tensor, name)?;
921	    let mut total = 0usize;
922	    for &(offset, len) in ranges {
923	        if offset + len > elems.len() {
924	            return Err(anyhow::anyhow!(
925	                "1D stitch out of bounds for '{}': offset={} len={} total_len={}",
926	                name,
927	                offset,
928	                len,
929	                elems.len()
930	            ));
931	        }
932	        total += len;
933	    }
934	    let mut host = Vec::with_capacity(total);
935	    for &(offset, len) in ranges {
936	        host.extend_from_slice(&elems[offset..offset + len]);
937	    }
938	    DeviceVec::from_host(ctx, &host)
939	}
