1050	/// Load shard info with fixup for mismatched shard filenames in index.json.
1051	///
1052	/// Some models (e.g., Qwen3.5) have index.json with shard filenames like
1053	/// `model.safetensors-00001-of-00002.safetensors` while actual files are
1054	/// `model-00001-of-00002.safetensors`. This function detects and fixes that.
1055	pub fn load_shard_info_fixed(model_path: &str) -> Result<(Vec<String>, HashMap<String, usize>)> {
1056	    let (mut shard_files, weight_map) = load_shard_info(model_path)?;
1057	
1058	    for path in &mut shard_files {
1059	        if !std::path::Path::new(path).exists() {
1060	            // Try replacing "model.safetensors-" with "model-" in filename
1061	            let filename = std::path::Path::new(path)
1062	                .file_name()
1063	                .unwrap()
1064	                .to_str()
1065	                .unwrap();
1066	            if let Some(rest) = filename.strip_prefix("model.safetensors-") {
1067	                let fixed = format!("{}/model-{}", model_path, rest);
1068	                if std::path::Path::new(&fixed).exists() {
1069	                    log::info!(
1070	                        "Fixed shard path: {} -> {}",
1071	                        filename,
1072	                        std::path::Path::new(&fixed)
1073	                            .file_name()
1074	                            .unwrap()
1075	                            .to_str()
1076	                            .unwrap()
1077	                    );
1078	                    *path = fixed;
1079	                    continue;
1080	                }
1081	            }
1082	            return Err(anyhow::anyhow!("Shard file not found: {}", path));
1083	        }
1084	    }
1085	
1086	    Ok((shard_files, weight_map))
1087	}
